// En capas: el negocio importa la capa de base de datos
import { NoteTable } from "../persistence/note-table";

// Hexagonal: el núcleo importa solo su propio puerto,
// y el adaptador de la base de datos importa el puerto
import type { NoteRepository } from "./ports/note-repository";

// use-cases/create-note.ts
import { Note } from "../entities/note";   // hacia adentro: permitido
import { PostgresNoteRepository }
  from "../drivers/postgres-note-repository"; // hacia afuera: VIOLACIÓN

export class Title {
	private constructor(public readonly value: string) {}

	static create(raw: string): Result<InvalidTitleError, Title> {
		const trimmed = raw.trim();
		if (trimmed.length === 0 || trimmed.length > 80) {
			return fail(new InvalidTitleError(raw));
		}
		return ok(new Title(trimmed));
	}
}

// adapters/http.ts: tipos propios, sin importar el framework
export type HttpRequest = { body: unknown; params: Record<string, string> };
export type HttpResponse = { statusCode: number; body: unknown };

// A: oculta, atada a PostgreSQL
private readonly notes = new PostgresNoteRepository();

// B: visible, reemplazable
constructor(private readonly notes: NoteRepository) {}

async function onOrderPaid(event: OrderPaid) {
	// Sin la comprobación, un evento repetido suma los puntos dos veces
	if (await alreadyProcessed(event.eventId)) return;
	await addPoints(event.customerId, event.points);
	await markProcessed(event.eventId);
}
